import sys

def greet(name="World"):
    """Returns a greeting string for the given name without a trailing newline."""
    return f"Hello, {name}"

def main():
    """Prints the greeting to stdout, handling command-line arguments."""
    if len(sys.argv) > 1:
        name = sys.argv[1]
    else:
        name = "World"

    # Requirement: Running python greet.py Ada prints exactly Hello, Ada! followed by a newline.
    # Requirement: Running python greet.py without arguments prints exactly Hello, World! followed by a newline.
    print(f"Hello, {name}!")

if __name__ == "__main__":
    main()
